// A comment's replies: "View N replies" loads them page by page from the
// comment's replies connection.
import { useCallback } from "react";
import { graphql, usePaginationFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { replyThreadTokens } from "ComponentTokens.stylex";
import fbt from "fbt";
import UIText from "UIText.react";
import UIIcon from "UIIcon.react";
import UIPressable from "UIPressable.react";
import { UIRow, UIColumn } from "UIStack.react";
import CommentBody from "CommentBody.react";
import { emitStepEvent } from "Workload";

const PAGE = 10;

const styles = stylex.create({
  thread: { paddingTop: 4, gap: replyThreadTokens.gap },
  toggle: { paddingBlock: 4, gap: 6 },
});

export default function CommentReplies({ comment }) {
  const { data, loadNext, hasNext, isLoadingNext } = usePaginationFragment(
    graphql`
      fragment CommentReplies_comment on Comment
      @refetchable(queryName: "CommentRepliesPaginationQuery")
      @argumentDefinitions(replyCount: { type: "Int", defaultValue: 0 }, replyCursor: { type: "String" }) {
        feedback {
          replies_fields {
            total_count
          }
          replies(first: $replyCount, after: $replyCursor) @connection(key: "CommentReplies_replies") {
            edges {
              node {
                id
                ...CommentBody_comment
              }
            }
          }
        }
      }
    `,
    comment,
  );
  const total = data.feedback?.replies_fields?.total_count ?? 0;
  const edges = data.feedback?.replies?.edges ?? [];
  const remaining = total - edges.length;
  const onLoad = useCallback(() => {
    loadNext(Math.min(PAGE * 3, remaining), { onComplete: () => emitStepEvent("replies-loaded") });
  }, [loadNext, remaining]);
  if (!total) {
    return null;
  }
  return (
    <UIColumn xstyle={styles.thread}>
      {edges.map((edge) => (
        <CommentBody key={edge.node.id} comment={edge.node} depth={1} />
      ))}
      {remaining > 0 && (hasNext || edges.length === 0) ? (
        <UIPressable label={`View ${remaining} replies`} onPress={onLoad} showOverlay={false} disabled={isLoadingNext} testid="view-replies">
          <UIRow xstyle={styles.toggle}>
            <UIIcon name="caretRight" size={14} />
            <UIText type="meta" color="secondary" weight="semibold">
              {fbt("View " + fbt.plural("reply", remaining, { many: "replies", showCount: "yes" }), "loads a comment's replies")}
            </UIText>
          </UIRow>
        </UIPressable>
      ) : null}
    </UIColumn>
  );
}
