// Like, Comment and Share. Hovering Like opens the reactions dock after the
// hover-intent delay; picking a reaction is local only (nothing is sent).
import { useCallback, useId, useState } from "react";
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import { ufiButtonTokens } from "ComponentTokens.stylex";
import fbt from "fbt";
import UIButton from "UIButton.react";
import { UIRow } from "UIStack.react";
import UFIReactionsDock from "UFIReactionsDock.react";
import { deferUntilFlush, cancelDeferred } from "TimerGuard";

const styles = stylex.create({
  bar: { position: "relative", marginInline: 12, paddingBlock: 4, borderTop: `1px solid ${colors.divider}`, gap: ufiButtonTokens.gap },
  likeWrap: { position: "relative", display: "flex", flexGrow: 1 },
});

export default function UFIActionBar({ feedback, onCommentPress }) {
  const data = useFragment(
    graphql`
      fragment UFIActionBar_feedback on Feedback {
        id
        can_viewer_react
        can_viewer_comment
        viewer_feedback_reaction_info {
          id
          localized_name
        }
        supported_reaction_infos {
          id
          localized_name
        }
      }
    `,
    feedback,
  );
  const [dockOpen, setDockOpen] = useState(false);
  const [localReaction, setLocalReaction] = useState(data.viewer_feedback_reaction_info?.id ?? null);
  const hoverKey = `reactions-dock:${useId()}`;
  const onPointerEnter = useCallback(() => deferUntilFlush(hoverKey, () => setDockOpen(true)), [hoverKey]);
  const onPointerLeave = useCallback(() => {
    cancelDeferred(hoverKey);
    setDockOpen(false);
  }, [hoverKey]);
  return (
    <UIRow xstyle={styles.bar}>
      <div onPointerEnter={onPointerEnter} onPointerLeave={onPointerLeave} data-hover-key={hoverKey} {...stylex.props(styles.likeWrap)}>
        {dockOpen ? (
          <UFIReactionsDock
            onPick={(type) => {
              setLocalReaction(type);
              setDockOpen(false);
            }}
          />
        ) : null}
        <UIButton label={localReaction ? localReaction[0] + localReaction.slice(1).toLowerCase() : fbt("Like", "UFI like button")} icon="like" use={localReaction ? "tertiary" : "flat"} grow testid="ufi-like" onPress={() => setLocalReaction((value) => (value ? null : "LIKE"))} />
      </div>
      <UIButton label={fbt("Comment", "UFI comment button")} icon="comment" use="flat" grow testid="ufi-comment" onPress={onCommentPress} disabled={!data.can_viewer_comment} />
      <UIButton label={fbt("Share", "UFI share button")} icon="share" use="flat" grow testid="ufi-share" />
    </UIRow>
  );
}
