// A top-level comment with its replies.
import { graphql, useFragment } from "react-relay";
import CommentBody from "CommentBody.react";
import CommentReplies from "CommentReplies.react";

export default function Comment({ comment }) {
  const data = useFragment(
    graphql`
      fragment Comment_comment on Comment {
        ...CommentBody_comment
        ...CommentReplies_comment
      }
    `,
    comment,
  );
  return (
    <CommentBody comment={data} depth={0}>
      <CommentReplies comment={data} />
    </CommentBody>
  );
}
