import { useState } from "react";
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { commentActionsTokens } from "ComponentTokens.stylex";
import fbt from "fbt";
import UIText from "UIText.react";
import UILink from "UILink.react";
import UIPressable from "UIPressable.react";
import { UIRow } from "UIStack.react";
import { shortRelativeTime } from "CurrentTime";

const styles = stylex.create({
  row: { gap: commentActionsTokens.gap, paddingInline: 12, paddingTop: 2 },
  action: { fontWeight: 700 },
});

export default function CommentActions({ comment }) {
  const data = useFragment(
    graphql`
      fragment CommentActions_comment on Comment {
        created_time
        is_edited
        url
        comment_action_links {
          key
          label
        }
      }
    `,
    comment,
  );
  const [liked, setLiked] = useState(false);
  return (
    <UIRow xstyle={styles.row}>
      <UILink href={data.url}>
        <UIText type="caption" color="secondary">
          {shortRelativeTime(data.created_time)}
        </UIText>
      </UILink>
      {data.comment_action_links?.map((link) => (
        <UIPressable key={link.key} label={link.label} showOverlay={false} onPress={link.key === "like" ? () => setLiked((value) => !value) : undefined} xstyle={styles.action}>
          <UIText type="caption" color={link.key === "like" && liked ? "accent" : "secondary"} weight="bold">
            {link.label}
          </UIText>
        </UIPressable>
      ))}
      {data.is_edited ? (
        <UIText type="caption" color="secondary">
          {fbt("Edited", "comment was edited")}
        </UIText>
      ) : null}
    </UIRow>
  );
}
