// A story in the feed. Each story nests its own surface, impression,
// error and context providers, as the reference's stories do.
import { createContext, Suspense, useMemo } from "react";
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { storyTokens } from "ComponentTokens.stylex";
import UICard from "UICard.react";
import UIErrorBoundary from "UIErrorBoundary.react";
import LoggingSurface from "LoggingSurface.react";
import { ImpressionContext } from "UIContexts";
import StoryHeader from "StoryHeader.react";
import StoryMessage from "StoryMessage.react";
import StoryAttachments from "StoryAttachments.react";
import StoryCallToAction from "StoryCallToAction.react";
import StoryFooter from "StoryFooter.react";
import StoryVideoParts from "StoryVideoParts.react";
import useImpression from "useImpression";

export const StoryContext = createContext(null);

const styles = stylex.create({
  card: { marginBottom: storyTokens.gap },
});

export default function FeedStory({ story, position, mode = "feed" }) {
  const data = useFragment(
    graphql`
      fragment FeedStory_story on Story {
        id
        post_id
        tracking
        comet_sections {
          context_layout {
            ...StoryHeader_contextLayout
          }
          content {
            ...StoryMessage_content
            ...StoryAttachments_content
          }
          feedback {
            ...StoryFooter_section
          }
        }
        ...StoryCallToAction_story
        ...StoryVideoParts_story @defer(label: "FeedStory_videoParts")
      }
    `,
    story,
  );
  const ref = useImpression(data.id, "story", data.tracking);
  const context = useMemo(() => ({ storyId: data.id, postId: data.post_id, position, mode }), [data.id, data.post_id, position, mode]);
  const sections = data.comet_sections;
  return (
    <StoryContext.Provider value={context}>
      <ImpressionContext.Provider value={data.tracking}>
        <LoggingSurface name="story">
          <UIErrorBoundary name="story">
            <UICard as="div" ref={ref} xstyle={mode === "feed" ? styles.card : null} role={mode === "feed" ? "article" : undefined} aria-posinset={position + 1} data-story-id={data.id} data-testid="feed-story">
              {sections?.context_layout ? <StoryHeader contextLayout={sections.context_layout} /> : null}
              {sections?.content ? <StoryMessage content={sections.content} /> : null}
              {sections?.content ? <StoryAttachments content={sections.content} /> : null}
              <StoryCallToAction story={data} />
              <Suspense fallback={null}>
                <StoryVideoParts story={data} />
              </Suspense>
              {sections?.feedback ? <StoryFooter section={sections.feedback} storyId={data.id} showComments={mode === "feed"} /> : null}
            </UICard>
          </UIErrorBoundary>
        </LoggingSurface>
      </ImpressionContext.Provider>
    </StoryContext.Provider>
  );
}
