// A comment without its replies: the author's avatar, a bubble with the
// name and text, its attachment, the reaction count and the action links.
import { useState } from "react";
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors, radii } from "BaseTokens.stylex";
import { commentBubbleTokens } from "ComponentTokens.stylex";
import fbt from "fbt";
import UIAvatar from "UIAvatar.react";
import UIText from "UIText.react";
import UILink from "UILink.react";
import UIImage from "UIImage.react";
import UIPressable from "UIPressable.react";
import { UIRow, UIColumn } from "UIStack.react";
import LoggingSurface from "LoggingSurface.react";
import TextWithEntities from "TextWithEntities.react";
import CommentActions from "CommentActions.react";
import CommentReactionCount from "CommentReactionCount.react";
import ProfileHovercardTrigger from "ProfileHovercardTrigger.react";
import useImpression from "useImpression";

const LONG_COMMENT = 360;

const styles = stylex.create({
  row: { alignItems: "flex-start", gap: 6, paddingBlock: 2 },
  bubbleWrap: { position: "relative", alignSelf: "flex-start", maxWidth: "100%" },
  bubble: { display: "inline-block", paddingBlock: 8, paddingInline: 12, borderRadius: radii.xxl, backgroundColor: colors.commentBackground, maxWidth: "100%", boxSizing: "border-box", whiteSpace: "pre-wrap" },
  attachment: { marginTop: 4, borderRadius: commentBubbleTokens.radius, overflow: "hidden" },
  sticker: { width: 120, height: 120 },
  photo: { width: 220, height: 160 },
  seeMore: { display: "inline", fontWeight: 600 },
  author: { display: "block" },
});

export default function CommentBody({ comment, depth = 0, children }) {
  const data = useFragment(
    graphql`
      fragment CommentBody_comment on Comment {
        id
        created_time
        is_edited
        depth
        url
        author {
          __typename
          id
          name
          url
          profile_picture(size: 32) {
            uri
          }
        }
        author_badges {
          key
          label
        }
        body {
          text
          ...TextWithEntities_text
        }
        attachments {
          kind
          media {
            id
            image(width: 220) {
              uri
            }
          }
        }
        feedback {
          id
          ...CommentReactionCount_feedback
        }
        ...CommentActions_comment
      }
    `,
    comment,
  );
  const [expanded, setExpanded] = useState(false);
  const ref = useImpression(data.id, "comment");
  const author = data.author;
  const text = data.body?.text ?? "";
  const truncate = !expanded && text.length > LONG_COMMENT ? LONG_COMMENT : null;
  const size = depth > 0 ? 24 : 32;
  return (
    <LoggingSurface name="comment">
      <div ref={ref} role="article" aria-label={`Comment by ${author?.name}`} data-comment-id={data.id}>
        <UIRow xstyle={styles.row}>
          <ProfileHovercardTrigger actorId={author?.id}>
            <UILink href={author?.url} label={author?.name}>
              <UIAvatar src={author?.profile_picture?.uri} size={size} />
            </UILink>
          </ProfileHovercardTrigger>
          <UIColumn grow>
            <div {...stylex.props(styles.bubbleWrap)}>
              {text ? (
                <div {...stylex.props(styles.bubble)}>
                  <UILink href={author?.url} strong xstyle={styles.author}>
                    <UIText type="meta" weight="semibold">
                      {author?.name}
                    </UIText>
                  </UILink>
                  {data.author_badges?.length ? (
                    <UIText type="caption" color="secondary">
                      {data.author_badges[0].label}
                    </UIText>
                  ) : null}
                  <UIText type="body">
                    <TextWithEntities text={data.body} truncateAt={truncate} />
                    {truncate !== null ? (
                      <>
                        {"... "}
                        <UIPressable as="span" label="See more" onPress={() => setExpanded(true)} showOverlay={false} xstyle={styles.seeMore}>
                          {fbt("See more", "Expands a long comment")}
                        </UIPressable>
                      </>
                    ) : null}
                  </UIText>
                </div>
              ) : null}
              {data.feedback ? <CommentReactionCount feedback={data.feedback} /> : null}
            </div>
            {data.attachments?.map((attachment) =>
              attachment.media?.image ? <UIImage key={attachment.media.id} src={attachment.media.image.uri} xstyle={[styles.attachment, attachment.kind === "STICKER" ? styles.sticker : styles.photo]} width={attachment.kind === "STICKER" ? 120 : 220} height={attachment.kind === "STICKER" ? 120 : 160} /> : null,
            )}
            <CommentActions comment={data} />
            {children}
          </UIColumn>
        </UIRow>
      </div>
    </LoggingSurface>
  );
}
