// The parts of a video story the server defers: the player configuration
// (read by the player when it starts) and the "up next" suggestions, plus a
// reel's footer.
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import UIText from "UIText.react";
import UIImage from "UIImage.react";
import { UIRow } from "UIStack.react";

const styles = stylex.create({
  chain: { paddingInline: 16, paddingBlock: 8, gap: 8, overflow: "hidden" },
  thumb: { borderRadius: 6, flexShrink: 0 },
});

export default function StoryVideoParts({ story }) {
  const data = useFragment(
    graphql`
      fragment StoryVideoParts_story on Story {
        video_parts {
          video {
            id
            video_player_config {
              autoplay_setting
              can_autoplay
              dash_manifest_url
              captions_url
              aspect_ratio
              logging_token
              quality_options {
                label
                height
                bitrate
              }
            }
          }
          chaining_suggestions {
            id
            title {
              text
            }
            poster_image {
              uri
            }
          }
        }
        reels_footer {
          title
          remix_count_text
          audio_title
        }
      }
    `,
    story,
  );
  const suggestions = data?.video_parts?.chaining_suggestions ?? [];
  if (!suggestions.length && !data?.reels_footer) {
    return null;
  }
  return (
    <>
      {data.reels_footer ? (
        <UIRow gap={8} xstyle={styles.chain}>
          <UIText type="meta" color="secondary" numberOfLines={1}>
            {data.reels_footer.audio_title} · {data.reels_footer.remix_count_text}
          </UIText>
        </UIRow>
      ) : null}
      {suggestions.length ? (
        <UIRow xstyle={styles.chain}>
          {suggestions.map((video) => (
            <UIImage key={video.id} src={video.poster_image?.uri} width={96} height={54} alt={video.title?.text ?? ""} xstyle={styles.thumb} />
          ))}
        </UIRow>
      ) : null}
    </>
  );
}
