// The top comments a story shows in the feed, with "View more comments",
// which opens the post dialog.
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import fbt from "fbt";
import UIText from "UIText.react";
import UIPressable from "UIPressable.react";
import { UIColumn } from "UIStack.react";
import Comment from "Comment.react";

const styles = stylex.create({
  list: { paddingInline: 16, paddingBottom: 8, gap: 4 },
  more: { paddingBlock: 4 },
});

export default function UFICommentsPreview({ feedback, onViewMore }) {
  const data = useFragment(
    graphql`
      fragment UFICommentsPreview_feedback on Feedback {
        comment_count {
          total_count
        }
        comment_rendering_instance {
          comments {
            edges {
              node {
                id
                ...Comment_comment
              }
            }
          }
        }
      }
    `,
    feedback,
  );
  const edges = data.comment_rendering_instance?.comments?.edges ?? [];
  if (!edges.length) {
    return null;
  }
  const total = data.comment_count?.total_count ?? 0;
  return (
    <UIColumn xstyle={styles.list}>
      {total > edges.length ? (
        <UIPressable label="View more comments" onPress={onViewMore} showOverlay={false} xstyle={styles.more} testid="view-more-comments">
          <UIText type="meta" color="secondary" weight="semibold">
            {fbt("View more comments", "opens the post dialog")}
          </UIText>
        </UIPressable>
      ) : null}
      {edges.map((edge) => (
        <Comment key={edge.node.id} comment={edge.node} />
      ))}
    </UIColumn>
  );
}
