import { Suspense } from "react";
import { graphql, useFragment } from "react-relay";
import FeedGlimmer from "FeedGlimmer.react";
import FeedStory from "FeedStory.react";
import PeopleYouMayKnowUnit from "PeopleYouMayKnowUnit.react";

export default function FeedUnit({ unit, position }) {
  const data = useFragment(
    graphql`
      fragment FeedUnit_unit on FeedUnit {
        __typename
        ...FeedStory_story @alias(as: "story")
        ...PeopleYouMayKnowUnit_unit @alias(as: "pymk")
      }
    `,
    unit,
  );
  // Each unit suspends on its own, so that one waiting for a renderer
  // module or deferred data doesn't hide the feed.
  if (data.story) {
    return (
      <Suspense fallback={<FeedGlimmer />}>
        <FeedStory story={data.story} position={position} />
      </Suspense>
    );
  }
  if (data.pymk) {
    return <PeopleYouMayKnowUnit unit={data.pymk} />;
  }
  return null;
}
