import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import { elevation } from "ElevationTokens.stylex";
import UIText from "UIText.react";
import UFIReactionIcons from "UFIReactionIcons.react";
import { compactCount } from "UICount";

const styles = stylex.create({
  pill: { position: "absolute", right: -8, bottom: -10, display: "flex", alignItems: "center", gap: 2, paddingInline: 3, paddingBlock: 1, borderRadius: 10, backgroundColor: colors.cardBackground, boxShadow: elevation.e1 },
});

export default function CommentReactionCount({ feedback }) {
  const data = useFragment(
    graphql`
      fragment CommentReactionCount_feedback on CommentFeedback {
        reaction_count {
          count
        }
        top_reactions(first: 2) {
          edges {
            node {
              id
            }
          }
        }
      }
    `,
    feedback,
  );
  const count = data.reaction_count?.count ?? 0;
  if (!count) {
    return null;
  }
  return (
    <span {...stylex.props(styles.pill)}>
      <UFIReactionIcons types={(data.top_reactions?.edges ?? []).map((edge) => edge.node.id)} />
      {count > 1 ? <UIText type="caption" color="secondary">{compactCount(count)}</UIText> : null}
    </span>
  );
}
