import { useState } from "react";
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { pymkCardTokens } from "ComponentTokens.stylex";
import UICard from "UICard.react";
import UIText from "UIText.react";
import UIImage from "UIImage.react";
import UIButton from "UIButton.react";
import UIIconButton from "UIIconButton.react";
import UILink from "UILink.react";
import { UIRow, UIColumn } from "UIStack.react";
import LoggingSurface from "LoggingSurface.react";

const styles = stylex.create({
  unit: { marginBottom: 16, paddingBlock: 12 },
  title: { paddingInline: 16, paddingBottom: 12 },
  scroller: { display: "flex", gap: 8, paddingInline: 16, overflowX: "auto" },
  card: { position: "relative", flexShrink: 0, width: 180, borderRadius: pymkCardTokens.radius, border: "1px solid rgba(0,0,0,0.1)", overflow: "hidden" },
  close: { position: "absolute", top: 6, right: 6 },
  body: { padding: 10, gap: 6 },
});

function Suggestion({ suggestion, onRemove }) {
  const user = suggestion.user;
  return (
    <div {...stylex.props(styles.card)}>
      <UILink href={user.url} block label={user.name}>
        <UIImage src={user.profile_picture?.uri} width={180} height={180} alt="" />
      </UILink>
      <UIIconButton icon="close" label="Remove" size={28} iconSize={14} onPress={onRemove} xstyle={styles.close} />
      <UIColumn xstyle={styles.body}>
        <UIText weight="semibold" numberOfLines={1}>
          {user.name}
        </UIText>
        <UIText type="meta" color="secondary" numberOfLines={1}>
          {suggestion.social_context}
        </UIText>
        <UIButton label="Add friend" use="tertiary" icon="friends" size="small" />
      </UIColumn>
    </div>
  );
}

export default function PeopleYouMayKnowUnit({ unit }) {
  const data = useFragment(
    graphql`
      fragment PeopleYouMayKnowUnit_unit on PeopleYouMayKnowUnit {
        id
        title
        suggestions {
          social_context
          tracking
          user {
            id
            name
            url
            profile_picture(size: 180) {
              uri
            }
          }
        }
      }
    `,
    unit,
  );
  const [removed, setRemoved] = useState(() => new Set());
  return (
    <LoggingSurface name="pymk">
      <UICard xstyle={styles.unit} data-testid="pymk-unit">
        <UIRow justify="between" xstyle={styles.title}>
          <UIText type="headline4">{data.title}</UIText>
        </UIRow>
        <div {...stylex.props(styles.scroller)}>
          {data.suggestions
            .filter((suggestion) => !removed.has(suggestion.user.id))
            .map((suggestion) => (
              <Suggestion key={suggestion.user.id} suggestion={suggestion} onRemove={() => setRemoved((set) => new Set(set).add(suggestion.user.id))} />
            ))}
        </div>
      </UICard>
    </LoggingSurface>
  );
}
