import { useCallback, useContext } from "react";
import { graphql, useFragment } from "react-relay";
import { RouterContext } from "RouterContext";
import LoggingSurface from "LoggingSurface.react";
import UFISummary from "UFISummary.react";
import UFIActionBar from "UFIActionBar.react";
import UFICommentsPreview from "UFICommentsPreview.react";

export default function StoryFooter({ section, storyId, showComments = true }) {
  const data = useFragment(
    graphql`
      fragment StoryFooter_section on StoryFeedbackSection {
        feedback_context {
          feedback_target_with_context {
            ufi_renderer {
              feedback {
                id
                ...UFISummary_feedback
                ...UFIActionBar_feedback
                ...UFICommentsPreview_feedback
              }
            }
          }
        }
      }
    `,
    section,
  );
  const router = useContext(RouterContext);
  const openPost = useCallback(() => router?.navigate(`/posts/${storyId}`), [router, storyId]);
  const feedback = data.feedback_context?.feedback_target_with_context?.ufi_renderer?.feedback;
  if (!feedback) {
    return null;
  }
  return (
    <LoggingSurface name="ufi">
      <UFISummary feedback={feedback} onCommentsPress={openPost} />
      <UFIActionBar feedback={feedback} onCommentPress={openPost} />
      {showComments ? <UFICommentsPreview feedback={feedback} onViewMore={openPost} /> : null}
    </LoggingSurface>
  );
}
